import React from 'react';
import { Outlet, Link, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { FaHome, FaUserMd, FaUsers, FaBox, FaSyringe, FaHeartbeat, FaClipboardList, FaChartLine, FaSignOutAlt } from 'react-icons/fa';

const DashboardLayout = () => {
  const { user, logout } = useAuth();
  const location = useLocation();

  const nurseNavItems = [
    { path: '/nurse/dashboard', icon: FaHome, label: 'Dashboard', color: 'text-blue-600' },
    { path: '/nurse/inventory', icon: FaBox, label: 'Inventory', color: 'text-green-600' },
    { path: '/nurse/students', icon: FaUsers, label: 'Students', color: 'text-purple-600' },
    { path: '/nurse/checkups', icon: FaHeartbeat, label: 'Health Checkups', color: 'text-red-600' },
    { path: '/nurse/vaccinations', icon: FaSyringe, label: 'Vaccinations', color: 'text-orange-600' },
    { path: '/nurse/record-event', icon: FaClipboardList, label: 'Record Event', color: 'text-teal-600' },
    { path: '/nurse/event-log', icon: FaClipboardList, label: 'Event Log', color: 'text-indigo-600' },
    { path: '/nurse/reports', icon: FaChartLine, label: 'Reports', color: 'text-pink-600' }
  ];

  const isActiveLink = (path) => {
    return location.pathname === path || location.pathname.startsWith(path + '/');
  };

  const handleLogout = () => {
    logout();
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <div className="w-64 bg-white shadow-lg">
        <div className="p-6 border-b">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center">
              <FaUserMd className="text-white text-lg" />
            </div>
            <div>
              <h3 className="font-semibold text-gray-900">{user?.fullName}</h3>
              <p className="text-sm text-gray-500">School Nurse</p>
            </div>
          </div>
        </div>

        <nav className="mt-6">
          <div className="px-4 space-y-2">
            {nurseNavItems.map(({ path, icon: Icon, label, color }) => (
              <Link
                key={path}
                to={path}
                className={`flex items-center space-x-3 px-4 py-3 rounded-lg transition-all duration-200 ${
                  isActiveLink(path)
                    ? 'bg-blue-50 text-blue-700 border-r-4 border-blue-600'
                    : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
                }`}
              >
                <Icon className={`text-lg ${isActiveLink(path) ? 'text-blue-600' : color}`} />
                <span className="font-medium">{label}</span>
              </Link>
            ))}
          </div>
        </nav>

        <div className="absolute bottom-0 w-64 p-4 border-t">
          <button
            onClick={handleLogout}
            className="flex items-center space-x-3 px-4 py-3 text-gray-600 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all duration-200 w-full"
          >
            <FaSignOutAlt className="text-lg" />
            <span className="font-medium">Logout</span>
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <header className="bg-white shadow-sm border-b px-6 py-4">
          <div className="flex items-center justify-between">
            <h1 className="text-2xl font-bold text-gray-900">
              School Health Management System
            </h1>
            <div className="flex items-center space-x-4">
              <div className="text-sm text-gray-500">
                {new Date().toLocaleDateString('en-US', { 
                  weekday: 'long', 
                  year: 'numeric', 
                  month: 'long', 
                  day: 'numeric' 
                })}
              </div>
            </div>
          </div>
        </header>

        {/* Content Area */}
        <main className="flex-1 p-6 overflow-auto">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default DashboardLayout;
